<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {localFetch,readJson} from './http'
import {segments} from './marginChecker'
type Range=[number,number]|null
type Change={amount:Range;pct:Range;compared_names:number;requested_names:number|null}
type Bin={index:number;label:string;amount:Range;share:Range;count:Range}
type Risk={active_names:number;cost_names:number;classified_names:number;pending_names:number;missing_cost_names:number;missing_price_names:number;loan:Range;maintenance:Range;buffer:Range;below130_amount:Range;below130_count:Range;bins:Bin[];cross_band_names:number;cost_filled_names:number;etf:boolean;count_applicable?:boolean;key?:string;label?:string;change20?:Change;source_missing_markets?:string[]}
type Stock={symbol:string;name:string;market:string;quantity:number;close:number|null;loan:Range;loan_mid:number|null;maintenance:Range;buffer:Range;band_min:number|null;band_max:number|null;change20:Change;cost_filled:boolean;initial_assumption:boolean}
type Point={date:string;maintenance:Range;loan:Range;covered_names:number;requested_names:number;complete:boolean}
type Group={key:string;label:string;count:number|null;metrics:Risk|null;change20:Change|null;change5_pp:Range;market_difference_pp:Range;members:Stock[]|null;points:Point[];status:string}
type Market={market:string;official_loan:number|null;official_maintenance:number|null;maintenance_lower_bound:boolean;missing_close_names:number;source_available:boolean;change20_amount:number|null;change20_pct:number|null;stock_risk:Risk|null}
type Report={version:string;status:string;model_ready:false;dates:string[];as_of:string;source_as_of:string;created_at:string;baseline20:string|null;markets:Market[];categories:{key:string;label:string}[];selected:Risk;cohort_market:string;groups:Group[];items:Stock[];chart_membership:string;range_note:string;vintage:string}
const data=ref<Report|null>(null),loading=ref(false),error=ref(''),date=ref(''),category=ref('listed_stock'),market=ref('TWSE'),search=ref(''),filter=ref('all'),sort=ref('loan'),page=ref(1),showMembers=ref(''),showDetails=ref(false),hover=ref<number|null>(null),chart=ref<HTMLDivElement|null>(null),viewport=ref(900)
let seq=0,disposed=false,observer:ResizeObserver|undefined
const fmt=(n:number|null|undefined,d=2)=>n==null?'—':n.toLocaleString('zh-TW',{maximumFractionDigits:d})
const money=(n:number|null|undefined)=>n==null?'—':Math.abs(n)>=1e8?fmt(n/1e8)+' 億':Math.abs(n)>=1e4?fmt(n/1e4)+' 萬':fmt(n)+' 元'
function range(r:Range|undefined,format:(n:number)=>string){if(!r)return '—';const a=format(r[0]),b=format(r[1]);return a===b?a:a+' ～ '+b}
const moneyRange=(r:Range|undefined)=>range(r,n=>money(n))
const percent=(n:number|null|undefined)=>n==null?'—':fmt(n*100)+'%'
const percentRange=(r:Range|undefined)=>range(r,n=>percent(n))
const signed=(n:number,d=2)=>(n>0?'+':'')+fmt(n,d)
const signedPercent=(n:number|null|undefined)=>n==null?'—':signed(n*100)+'%'
const changeRange=(r:Range|undefined)=>range(r,n=>signedPercent(n))
const ppRange=(r:Range|undefined)=>range(r,n=>signed(n))
const countRange=(r:Range|undefined)=>range(r,n=>fmt(n,0))
const bandLabels=['已破130%','緩衝0～7%','緩衝7～13%','緩衝13～22%','緩衝>22%']
const bandApprox=['<130%','約130～140%','約140～150%','約150～166.7%','>166.7%']
const colors=['#ba5c53','#ce8c47','#bdad54','#71947b','#648da5']
const groupColors=['#597aab','#a17a50','#76936c','#9b78aa']
const mid=(r:Range|undefined)=>r?(r[0]+r[1])/2:null
const sourceMissing=computed(()=>data.value?.selected.source_missing_markets?.length===((category.value==='listed_stock'||category.value==='otc_stock')?1:2))
const filtered=computed(()=>{let rows=(data.value?.items||[]).filter(r=>(!search.value||(r.symbol+' '+r.name).toLowerCase().includes(search.value.toLowerCase()))&&(filter.value==='all'||filter.value==='pending'&&r.band_min==null||filter.value==='below'&&r.band_min===0||filter.value==='cross'&&r.band_min!==r.band_max));rows=[...rows].sort((a,b)=>{const x=sort.value==='maintenance'?mid(a.maintenance):sort.value==='change'?mid(a.change20.amount):a.loan_mid,y=sort.value==='maintenance'?mid(b.maintenance):sort.value==='change'?mid(b.change20.amount):b.loan_mid;return x==null?y==null?a.symbol.localeCompare(b.symbol):1:y==null?-1:sort.value==='maintenance'?x-y:y-x});return rows})
const maxPage=computed(()=>Math.max(1,Math.ceil(filtered.value.length/50))),items=computed(()=>filtered.value.slice((page.value-1)*50,page.value*50))
const memberGroup=computed(()=>data.value?.groups.find(g=>g.key===showMembers.value))
const points=computed(()=>data.value?.groups[0]?.points||[]),width=computed(()=>Math.max(720,viewport.value)),left=68,right=24,top=30,bottom=245
const x=(i:number)=>left+i/Math.max(1,points.value.length-1)*(width.value-left-right)
const chartRange=computed(()=>{const values=[1.3,...(data.value?.groups.flatMap(g=>g.points.flatMap(p=>p.maintenance||[]))||[])];const lo=Math.min(...values),hi=Math.max(...values),pad=Math.max((hi-lo)*.12,.05);return [Math.max(0,lo-pad),hi+pad]})
const y=(n:number)=>bottom-(n-chartRange.value[0]!)/(chartRange.value[1]!-chartRange.value[0]!)*(bottom-top)
const activeIndex=computed(()=>hover.value??Math.max(0,points.value.length-1)),chartDate=computed(()=>points.value[activeIndex.value]?.date||data.value?.as_of)
const paths=computed(()=>data.value?.groups.map((g,i)=>({key:g.key,label:g.label,color:groupColors[i],paths:segments(g.points.map(p=>mid(p.maintenance)),x,y),active:g.points[activeIndex.value]}))||[])
const dateTicks=computed(()=>[...new Set([0,Math.floor((points.value.length-1)/2),points.value.length-1])].filter(i=>i>=0))
function remember(){try{localStorage.setItem('margin-observation.preferences.v1',JSON.stringify({category:category.value,market:market.value,showDetails:showDetails.value}))}catch{}}
function move(e:PointerEvent){const b=(e.currentTarget as SVGElement).getBoundingClientRect();hover.value=Math.max(0,Math.min(points.value.length-1,Math.round(((e.clientX-b.left)/b.width*width.value-left)/(width.value-left-right)*Math.max(1,points.value.length-1))))}
async function load(){const id=++seq;loading.value=true;error.value='';hover.value=null;try{const q=new URLSearchParams({category:category.value,market:market.value});if(date.value)q.set('date',date.value);const r=await localFetch('/api/margin-statistics/risk?'+q);const v=await readJson<Report&{error?:string}>(r);if(!r.ok)throw Error(v.error||'讀取融資觀察失敗');if(id===seq&&!disposed){data.value=v;page.value=1;showMembers.value='';remember();await nextTick();if(chart.value){observer?.disconnect();observer?.observe(chart.value);viewport.value=chart.value.clientWidth}}}catch(e){if(id===seq&&!disposed)error.value=e instanceof Error?e.message:String(e)}finally{if(id===seq&&!disposed)loading.value=false}}
function changeCategory(){if(category.value==='listed_stock')market.value='TWSE';if(category.value==='otc_stock')market.value='TPEX';filter.value='all';load()}
function changeMarket(m:string){market.value=m;load()}
function toggleDetails(e:Event){showDetails.value=(e.target as HTMLDetailsElement).open;remember()}
watch([search,filter,sort],()=>page.value=1)
onMounted(()=>{try{const p=JSON.parse(localStorage.getItem('margin-observation.preferences.v1')||'{}');if(['listed_stock','otc_stock','etf_cap','etf_dividend','etf_leverage','etf_inverse','other','all_etf'].includes(p.category))category.value=p.category;if(['TWSE','TPEX'].includes(p.market))market.value=p.market;if(typeof p.showDetails==='boolean')showDetails.value=p.showDetails}catch{};observer=new ResizeObserver(e=>{const w=e[0]?.contentRect.width;if(w&&Math.abs(w-viewport.value)>1)viewport.value=w});load()})
onUnmounted(()=>{disposed=true;seq++;observer?.disconnect()})
</script>
<template>
 <div class="financing-risk" :aria-busy="loading">
  <header class="page-heading"><div><div class="eyebrow">MARGIN FINANCING · MARKET & POSITIONS</div><h1>融資維持率統計</h1><p>看融資變化、130%緩衝與個股風險分布。</p></div><div class="date-controls"><label>查看交易日<select v-model="date" aria-label="融資觀察交易日" :disabled="loading" @change="load"><option value="">最新 · {{data?.source_as_of||'讀取中'}}</option><option v-for="d in [...(data?.dates||[])].reverse()" :key="d" :value="d">{{d}}</option></select></label><button :disabled="loading" @click="load">{{loading?'讀取中…':'重新讀取'}}</button></div></header>
  <p v-if="error" role="alert" class="notice error">{{error}}</p><p v-if="data?.status==='missing'" class="notice">觀察資料尚未建立。</p>
  <template v-else-if="data?.selected">
   <div class="market-cards" aria-label="上市與上櫃融資摘要"><article v-for="m in data.markets" :key="m.market" :data-market="m.market"><div class="card-title"><h2>{{m.market==='TWSE'?'上市':'上櫃'}}</h2><span>{{data.as_of}}</span></div><div class="maintenance"><small>大盤融資維持率 <em>官方推導</em></small><strong>{{m.maintenance_lower_bound?'≥ ':''}}{{percent(m.official_maintenance)}}</strong><p v-if="m.missing_close_names">缺收盤 {{m.missing_close_names}} 檔，顯示可定價部位的下限</p><p v-else>融資部位市值 ÷ 官方融資金額</p></div><div class="stress"><small>個股 &lt;130% <em>估算</em></small><div><b>{{countRange(m.stock_risk?.below130_count)}} <span>檔</span></b><b>{{moneyRange(m.stock_risk?.below130_amount)}}</b></div><p v-if="m.stock_risk">可分級 {{m.stock_risk.classified_names}}／{{m.stock_risk.active_names}} 檔<template v-if="m.stock_risk.pending_names"> · 另 {{m.stock_risk.pending_names}} 檔待分級</template><template v-if="m.stock_risk.cost_filled_names"> · 含成本補估 {{m.stock_risk.cost_filled_names}} 檔</template></p><p v-else>本日缺來源，不當成0檔。</p></div><div class="official-amount"><div><small>官方融資金額</small><b>{{money(m.official_loan)}}</b></div><div><small>20日變化</small><b>{{signedPercent(m.change20_pct)}}</b><span>{{m.change20_amount==null?'—':(m.change20_amount>0?'+':'')+money(m.change20_amount)}}</span></div></div></article></div>
   <p class="caption">「估算」顯示兩種算法的差異，並非真實上下限；含成本補估的部位另標示。</p>
   <section class="panel distribution" aria-label="融資五格風險分布"><div class="section-heading"><div><h2>融資風險分布</h2><p>金額為主，家數為輔 · 平均成本／FIFO估算範圍</p></div><label>資產別<select v-model="category" aria-label="融資風險資產別" :disabled="loading" @change="changeCategory"><option v-for="c in data.categories" :key="c.key" :value="c.key">{{c.label}}</option></select></label></div><div v-if="sourceMissing" class="notice">本日缺{{data.selected.label}}融資來源，沒有把缺值當成0。</div><template v-else><p v-if="data.selected.source_missing_markets?.length" class="caption">缺少 {{data.selected.source_missing_markets.join('、')}} 來源，以下是已保存部位的估算小計。</p><div class="basket-summary"><span>{{data.selected.label}}可估融資 <b>{{moneyRange(data.selected.loan)}}</b></span><span>20日變化 <b>{{changeRange(data.selected.change20?.pct)}}</b><small>同檔比較 {{data.selected.change20?.compared_names}}／{{data.selected.change20?.requested_names??'—'}} 檔</small></span><span>可分級 <b>{{data.selected.classified_names}}／{{data.selected.active_names}}</b><small>另 {{data.selected.pending_names}} 檔待分級</small></span></div><div class="table-scroll" tabindex="0" aria-label="五格融資分布，可左右捲動"><table class="bands"><thead><tr><th></th><th v-for="(b,i) in data.selected.bins" :key="b.index" :style="{'--band':colors[i]}">{{bandLabels[i]}}<small>{{bandApprox[i]}}</small></th></tr></thead><tbody><tr><th>融資金額<small>估算</small></th><td v-for="b in data.selected.bins" :key="b.index"><strong v-if="b.amount" class="amount-range"><span>{{money(b.amount[0])}}</span><template v-if="money(b.amount[0])!==money(b.amount[1])"><small>～</small><span>{{money(b.amount[1])}}</span></template></strong><strong v-else>—</strong></td></tr><tr><th>金額占比</th><td v-for="b in data.selected.bins" :key="b.index">{{percentRange(b.share)}}</td></tr><tr v-if="data.selected.count_applicable"><th>家數</th><td v-for="b in data.selected.bins" :key="b.index">{{countRange(b.count)}}</td></tr></tbody></table></div><p class="caption">占比以可分級部位的估算融資金額為分母。{{data.selected.etf?'ETF只列金額與占比，不列風險家數。':data.selected.count_applicable?data.selected.cross_band_names+' 檔會因算法不同而跨級。':'其他商品只列金額與占比。'}}<template v-if="data.selected.cost_filled_names"> 含 {{data.selected.cost_filled_names}} 檔成本補估。</template>各格區間端點不能直接相加。</p></template></section>
   <section class="panel cohorts" aria-label="四種融資子集"><div class="section-heading"><div><h2>個股子集 · 融資變化與風險</h2><p>個股分市場，不混ETF；點選名稱可看成員。</p></div><div class="segmented" role="group" aria-label="子集市場"><button :aria-pressed="market==='TWSE'" :disabled="loading" @click="changeMarket('TWSE')">上市</button><button :aria-pressed="market==='TPEX'" :disabled="loading" @click="changeMarket('TPEX')">上櫃</button></div></div><div class="table-scroll"><table class="cohort-table"><thead><tr><th>子集／檔數</th><th>維持率 · 估算</th><th>與個股全體差<small>百分點</small></th><th>&lt;130%金額 · 估算</th><th>20日融資變化</th><th>5日維持率變化<small>百分點</small></th></tr></thead><tbody><tr v-for="(g,i) in data.groups" :key="g.key" :data-cohort="g.key"><td><button class="member-button" :style="{color:groupColors[i]}" @click="showMembers=showMembers===g.key?'':g.key">{{g.label}}</button><small>{{g.count==null?'缺同日來源':g.count+' 檔'}}<template v-if="g.metrics?.pending_names"> · {{g.metrics.pending_names}} 檔待分級</template></small></td><td>{{percentRange(g.metrics?.maintenance)}}</td><td>{{ppRange(g.market_difference_pp)}}</td><td>{{moneyRange(g.metrics?.below130_amount)}}</td><td>{{changeRange(g.change20?.pct)}}<small>{{moneyRange(g.change20?.amount)}} · {{g.change20?.compared_names??'—'}} 檔</small></td><td>{{ppRange(g.change5_pp)}}</td></tr></tbody></table></div>
    <div v-if="memberGroup" class="members"><h3>{{memberGroup.label}} · {{memberGroup.count??'—'}} 檔</h3><p v-if="!memberGroup.members">缺少該日來源，不借用其他日期的名單。</p><div v-else class="member-chips"><span v-for="r in memberGroup.members" :key="r.symbol"><b>{{r.name}}</b> {{r.symbol}}<small>{{percentRange(r.maintenance)}}</small></span></div></div>
    <div class="subset-chart"><div class="chart-heading"><h3>子集維持率線 · 近30交易日</h3><span data-cohort-chart-date>{{hover==null?'查閱日':'游標'}} {{chartDate}}</span></div><div class="legend"><div v-for="g in paths" :key="g.key"><i :style="{background:g.color}"></i><span>{{g.label}}</span><b>{{percentRange(g.active?.maintenance)}}</b><small>{{g.active?.covered_names??0}}／{{g.active?.requested_names??0}} 檔</small></div></div><div ref="chart" class="chart-scroll" tabindex="0" aria-label="融資子集維持率線，可左右捲動"><svg :width="width" height="295" :viewBox="`0 0 ${width} 295`" role="img" aria-label="四種個股子集維持率估算線" @pointermove="move" @pointerleave="hover=null"><rect :width="width" height="295" fill="white"/><g v-for="v in [chartRange[0]!,((chartRange[0]!+chartRange[1]!)/2),chartRange[1]!]" :key="v"><line :x1="left" :x2="width-right" :y1="y(v)" :y2="y(v)" class="grid"/><text :x="left-8" :y="y(v)+4" text-anchor="end" class="axis">{{fmt(v*100,0)}}%</text></g><line :x1="left" :x2="width-right" :y1="y(1.3)" :y2="y(1.3)" class="danger-line"/><text :x="width-right" :y="y(1.3)-6" text-anchor="end" class="danger-label">130%</text><g v-for="g in paths" :key="g.key"><path v-for="(p,i) in g.paths" :key="i" :d="p" :stroke="g.color" class="series"/><circle v-if="g.active?.maintenance" :cx="x(activeIndex)" :cy="y(mid(g.active.maintenance)!)" r="4" :fill="g.active.complete?g.color:'white'" :stroke="g.color" stroke-width="2"/></g><line v-if="points.length" :x1="x(activeIndex)" :x2="x(activeIndex)" :y1="top" :y2="bottom" class="cursor"/><text v-for="i in dateTicks" :key="i" :x="x(i)" y="279" :text-anchor="i===0?'start':i===points.length-1?'end':'middle'" class="axis">{{points[i]?.date}}</text></svg></div><p class="caption">線為兩法中值，圖例顯示估算範圍。{{data.chart_membership}}。空心點表示成員資料未齊；每天涵蓋不同可能影響曲線。</p></div>
   </section>
   <section class="panel securities" aria-label="個股與ETF融資清單"><div class="section-heading"><div><h2>{{data.selected.label}} · 融資清單</h2><p>維持率與分級都是估算；跨級代表兩種算法落在不同區間。</p></div></div><div class="list-controls"><input v-model="search" aria-label="搜尋融資股票ETF" placeholder="代碼或名稱"/><label>篩選<select v-model="filter" aria-label="融資風險篩選"><option value="all">全部</option><option value="below">任一算法低於130%</option><option value="cross">兩法分級不同</option><option value="pending">待分級</option></select></label><label>排序<select v-model="sort" aria-label="融資清單排序"><option value="loan">融資金額大到小</option><option value="maintenance">維持率低到高</option><option value="change">20日增加金額</option></select></label></div><div class="table-scroll" tabindex="0"><table class="stock-table"><thead><tr><th>標的</th><th>收盤／融資張數</th><th>維持率 · 估算</th><th>距130%跌幅</th><th>融資金額 · 估算</th><th>20日變化</th><th>風險分級</th></tr></thead><tbody><tr v-for="r in items" :key="r.market+r.symbol"><td><b>{{r.name}}</b><small>{{r.symbol}} <span v-if="r.cost_filled">· 含成本補估</span></small></td><td>{{fmt(r.close)}}<small>{{fmt(r.quantity,0)}} 張</small></td><td>{{percentRange(r.maintenance)}}</td><td>{{percentRange(r.buffer)}}</td><td>{{moneyRange(r.loan)}}</td><td>{{changeRange(r.change20.pct)}}<small>{{moneyRange(r.change20.amount)}}</small></td><td><span v-if="r.band_min!=null" class="risk-badge" :style="{color:colors[r.band_min]}">{{r.band_min===r.band_max?bandLabels[r.band_min]:'跨 '+bandLabels[r.band_min]+' ～ '+bandLabels[r.band_max!]}}</span><span v-else class="pending">待分級</span></td></tr><tr v-if="!items.length"><td colspan="7" class="empty">{{loading?'讀取中…':'沒有符合的融資部位'}}</td></tr></tbody></table></div><div class="pagination"><span>{{fmt(filtered.length,0)}} 檔</span><button :disabled="page<=1" @click="page--">上一頁</button><b>{{page}} / {{maxPage}}</b><button :disabled="page>=maxPage" @click="page++">下一頁</button></div></section>
   <details class="panel methodology" :open="showDetails" @toggle="toggleDetails"><summary>計算口徑與資料說明</summary><p>大盤維持率＝同日全部融資標的「張數×1000×收盤」加總÷官方融資金額，含ETF。缺收盤時顯示可定價分子的下限，標示「≥」，不假裝精確全市場值；不是券商整戶擔保率。</p><p>{{data.range_note}} 缺成本先沿用同檔既有單位借款代理成本；沒有歷史成本時才用當時可得行情初始化補估。含補估的部位另有標記，兩法相同也不代表成本已知。</p><p>距130%跌幅＝1−130%÷維持率；分級依此精確計算，表頭維持率是約數。五格依本金金額加權，家數僅作輔助；ETF不彙總風險家數。</p><p>融資前30與增加前30以兩法中值排序；20日增加榜只取增加者。RS採同市場、有融資個股的同日20日RS前30；YTD採同日超額大盤&gt;0。子集固定查閱日成員回看；與個股全體差距採同方法、可分級個股計算。20日與5日變化按交易日曆同檔比較，缺基期不填0。</p><p>目前只作風險觀察，不啟用買賣訊號；原包2交易採用驗收與研究檔保留，不再鎖住這裡的觀察值。</p><p>資料截止 {{data.source_as_of}} · 本次保存 {{data.created_at.slice(0,16).replace('T',' ')}} · {{data.vintage}}。</p><p>來源：<a href="https://www.twse.com.tw/zh/trading/margin/mi-margn.html" target="_blank" rel="noopener">臺灣證券交易所 ↗</a> · <a href="https://www.tpex.org.tw/zh-tw/mainboard/trading/margin-trading/transactions.html" target="_blank" rel="noopener">櫃買中心 ↗</a></p></details>
  </template><p v-else-if="loading" class="notice">正在讀取融資觀察…</p>
 </div>
